// D-OS CTX-74 File
// The system works with this file.
// Please, DO NOT EDIT THIS FILE UNLESS YOU KNOW WHAT YOU ARE DOING! (And if it's a mod. You can make mods for any OS actually...)

const comp_display = document.getElementById('comp-display-ctx74');
comp_display.style.backgroundColor = 'rgb(0, 0, 0)';
let readyForUI = false;
let runningTasks = [];




function callBooter(){
    if(!readyForUI){
        comp_display.innerHTML = '<pre style="color: #00FF00; font-family: \'Cascadia Code\', monospace; font-size: 14px; margin: 10px; user-select: none;">2024 Copyright AOS Systems\n';
        setTimeout(() => {
            comp_display.innerHTML += '<pre style="color: #00FF00; font-family: \'Cascadia Code\', monospace; font-size: 14px; margin: 10px; user-select: none;">Intializing Booter...';
        }, 1000);
        setTimeout(() => {
            comp_display.innerHTML += '<pre style="color: #00FF00; font-family: \'Cascadia Code\', monospace; font-size: 14px; margin: 10px; user-select: none;">Loading nerdy GUI stuff...';
        }, 2000);
        setTimeout(() => {
            comp_display.innerHTML += '<pre style="color: #00FF00; font-family: \'Cascadia Code\', monospace; font-size: 14px; margin: 10px; user-select: none;">Removing cache...';
        }, 5000);
        setTimeout(() => {
            comp_display.innerHTML += '<pre style="color: #00FF00; font-family: \'Cascadia Code\', monospace; font-size: 14px; margin: 10px; user-select: none;">Starting up...';
        }, 7000);
        setTimeout(() => {
            clearText();
        }, 9000);
    }
}

function clearText(){
    comp_display.innerHTML = '';
    readyForUI = true;

    loadUI();
}

function loadUI(){
    if(readyForUI){
        comp_display.style.backgroundColor = 'rgb(0, 132, 255)';
        comp_display.innerHTML = `<h1 style="color: white; font-family: sans-serif;">Welcome to D-OS CTX-74!</h1>
        <p style="color: white; font-family: sans-serif;">Click the button below to login.</p>
        <button style="background-color:rgb(0, 88, 170); font-family: \'Cascadia Code\'; border:none;" onclick="login()">Login</button>`;
    }
}
function login(){
    clearText();
    comp_display.innerHTML = `
    <div class="taskbar-ctx74" style="position: absolute; bottom: 16.8vh; width: 780px; height: 40px; background-color: rgb(0, 88, 170); display: flex; align-items: center; padding: 0 10px;">
        <button style="background-color: rgb(0, 132, 255); border: none; color: white; font-family: 'Cascadia Code'; padding: 5px 10px; cursor: pointer;" onclick="startMenu()">Start</button>
    </div>
    `;
}

function startMenu(){
    const existingMenu = document.getElementById('start-menu-ctx74');
    if(existingMenu){
        existingMenu.remove();
        runningTasks.splice(runningTasks.indexOf('menu.list'), 1);
    } else {
        comp_display.innerHTML += `
        <div class="start-menu-ctx74" id="start-menu-ctx74">
            <h3 style="color: white; font-family: 'Cascadia Code'; margin: 0 0 10px 0;">Start Menu</h3>
            <ul style="list-style: none; padding: 0; margin: 0;">
                <li style="margin-bottom: 5px;"><button style="width: 100%; background-color: rgb(0, 132, 255); border: none; color: white; font-family: 'Cascadia Code'; padding: 5px 0; cursor: pointer;" onclick="document.getElementById('start-menu-ctx74').remove(); runningTasks.splice(runningTasks.indexOf('menu.list'), 1);">Close</button></li>
                <li style="margin-bottom: 5px;"><button style="width: 100%; background-color: rgb(0, 132, 255); border: none; color: white; font-family: 'Cascadia Code'; padding: 5px 0; cursor: pointer;" onclick="taskManager()">Task Manager</button></li>
                <li><button style="width: 100%; background-color: rgb(0, 132, 255); border: none; color: white; font-family: 'Cascadia Code'; padding: 5px 0; cursor: pointer;">Shutdown</button></li>
            </ul>
        </div>
        `;
        runningTasks.push("menu.list");
    }
}

class makeWindow{
    constructor(title, content, id){
        this.title = title;
        this.content = content;
        this.id = id;
        this.createWindow();
    }
    createWindow(){
        if(!document.getElementById(this.id)){
            comp_display.innerHTML += `<div class="window-ctx74" id="${this.id}"><h3 style="font-family: 'Cascadia Code'; margin: 0; padding: 10px; background-color: #00425a; border-bottom: 1px solid #000000; user-select: none;">${this.title}</h3><div style="padding: 10px; user-select: none;">${this.content}</div></div>`;
        }
    }
}

function taskManager(){
    runningTasks.push('Task Manager');
    new makeWindow('Task Manager', `<h2 style="font-family: 'Cascadia Code';">Task Manager</h2><p style="font-family: 'Cascadia Code'; color:white;">Current tasks running:</p><br><p  style="font-family: 'Cascadia Code'; color:white;">${runningTasks}</p><button style="background-color: rgb(0, 132, 255); color: white; font-family: 'Cascadia code'; padding: 5px; cursor: pointer; border: none; width: 30%;" onclick="document.getElementById('task-manager-ctx74').remove(); runningTasks.splice(runningTasks.indexOf('Task Manager'), 1);">Close</button>`, 'task-manager-ctx74');
}




callBooter();
